CREATE OR REPLACE FORCE VIEW PAR_OWNER.FPL_V_AR_CLO_AMS_ACCOUNTING_EVENTS
(
    PAR_SOURCE,
    PAR_STATUS,
    PAR_TIMESTAMP,
    AEF_EVENT_CODE,
    AEF_EVENT_DATE,
    AEF_NOTE
)
BEQUEATH DEFINER
AS
    SELECT 'CLO'       AS PAR_SOURCE,
           0           AS PAR_STATUS,
           SYSDATE     AS PAR_TIMESTAMP,
           AEF_EVENT_CODE,
           AEF_EVENT_DATE,
           UPPER(AEF_OFFER_ID) AS AEF_NOTE
      FROM CLO_AMS_ACCOUNTING_EVENTS_1@fpl_par
/
